function newHandle(before, after) {
  const known = new Set(before);
  const fresh = after.filter(h => !known.has(h));
  if (fresh.length === 0) throw new Error('no new window');
  if (fresh.length > 1) throw new Error('multiple new windows');
  return fresh[0];
}

function framePath(page, elementId) {
  if (page.elements.includes(elementId)) return [];
  for (const f of page.frames || []) {
    const sub = framePath(f, elementId);
    if (sub !== null) return [f.name, ...sub];
  }
  return null;
}
